mapper.select:
SELECT substr(EM.Assignment_Category,INSTR(EM.Assignment_Category,'_')+1,LENGTH(EM.Assignment_Category)-INSTR(EM.Assignment_Category,'_')+1) AS "emp_cat" ,SUBSTR(EM.Email, 1, INSTR(EM.Email,'@')-1) AS "USER_ID" ,EM.Full_Name_Local ,EM.EMPLOYEE_NUMBER ,lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', EM.grade_title) AS "grade_title" ,EM.Attribute10 AS SHIFT_CODE --MON ,MAX(DECODE(tar.a_day_of_the_week_code, 'MON', lgvatt_common_pkg.get_att_code_info('LGDVN',tar.time_and_attendance_code),NULL)) AS mon_att_code ,SUM(DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.work_hours,0),NULL)) - (SUM(DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.going_out_hours,0),null))) AS mon_nomal_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.public_holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', NVL(taso.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', NVL(taso.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', NVL(taso.public_holiday_overtime_hours,0),null)) AS mon_ot_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(taso.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(taso.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(taso.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(taso.public_holiday_night_ot_hours,0),null)) AS mon_night_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.normal_night_overtime_hours,0),null)) AS mon_ot_at_night ,SUM(DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'MON', nvl(tar.going_out_hours,0),null)) AS mon_deduction --TUE ,MAX(DECODE(tar.a_day_of_the_week_code, 'TUE', lgvatt_common_pkg.get_att_code_info('LGDVN',tar.time_and_attendance_code),NULL)) AS tue_att_code ,SUM(DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.work_hours,0),NULL)) -(SUM(DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.going_out_hours,0),null))) AS tue_nomal_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.public_holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.public_holiday_overtime_hours,0),null)) AS tue_ot_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(taso.public_holiday_night_ot_hours,0),null)) AS tue_night_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.normal_night_overtime_hours,0),null)) AS tue_ot_at_night ,SUM(DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'TUE', nvl(tar.going_out_hours,0),null)) AS tue_deduction --WED ,MAX(DECODE(tar.a_day_of_the_week_code, 'WED', lgvatt_common_pkg.get_att_code_info('LGDVN',tar.time_and_attendance_code),NULL)) AS wed_att_code ,SUM(DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.work_hours,0),NULL)) -(SUM(DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.going_out_hours,0),null))) AS wed_nomal_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.public_holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(taso.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(taso.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(taso.public_holiday_overtime_hours,0),null)) AS wed_ot_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'WED', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_