_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(taso.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(taso.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(taso.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(taso.public_holiday_night_ot_hours,0),null)) AS thu_night_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'THU', nvl(tar.normal_night_overtime_hours,0),null)) AS thu_ot_at_night ,SUM(DECODE(tar.a_day_of_the_week_code, 'THU', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'THU', nvl(tar.going_out_hours,0),null)) AS thu_deduction --FRI ,MAX(DECODE(tar.a_day_of_the_week_code, 'FRI', lgvatt_common_pkg.get_att_code_info('LGDVN',tar.time_and_attendance_code),NULL)) AS fri_att_code ,SUM(DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.work_hours,0),NULL)) -(SUM(DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.going_out_hours,0),null))) AS fri_nomal_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.public_holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.public_holiday_overtime_hours,0),null)) AS fri_ot_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(taso.public_holiday_night_ot_hours,0),null)) AS fri_night_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.normal_night_overtime_hours,0),null)) AS fri_ot_at_night ,SUM(DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'FRI', nvl(tar.going_out_hours,0),null)) AS fri_deduction --SAT ,MAX(DECODE(tar.a_day_of_the_week_code, 'SAT', lgvatt_common_pkg.get_att_code_info('LGDVN',tar.time_and_attendance_code),NULL)) AS sat_att_code ,SUM(DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.work_hours,0),NULL)) -(SUM(DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.going_out_hours,0),null))) AS sat_nomal_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.public_holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.public_holiday_overtime_hours,0),null)) AS sat_ot_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(taso.public_holiday_night_ot_hours,0),null)) AS sat_night_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.normal_night_overtime_hours,0),null)) AS sat_ot_at_night ,SUM(DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SAT', nvl(tar.going_out_hours,0),null)) AS sat_deduction --SUN ,MAX(DECODE(tar.a_day_of_the_week_code, 'SUN', lgvatt_common_pkg.get_att_code_info('LGDVN',tar.time_and_attendance_code),NULL)) AS sun_att_code ,SUM(DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.work_hours,0),NULL)) -(SUM(DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.going_out_hours,0),null))) AS sun_nomal_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.public_holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.weekday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.holiday_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.public_holiday_overtime_hours,0),null)) AS sun_ot_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.public_holiday_night_ot_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.weekday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.weekday_ot_af_night_work_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.holiday_night_overtime_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(taso.public_holiday_night_ot_hours,0),null)) AS sun_night_time ,SUM(DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.normal_night_overtime_hours,0),null)) AS sun_ot_at_night ,SUM(DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.tardy_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.early_leave_hours,0),null) +DECODE(tar.a_day_of_the_week_code, 'SUN', nvl(tar.going_out_hours,0),null)) AS sun_deduction FROM EMP_MASTER EM ,TB_ATT_RESULT_N TAR ,TB_ATT_SPECIAL_OT_RESULT_N TASO where 1=1 AND EM.FSE_YN = 'N' AND EM.FLSA_YN = 'N'
AND EM.Attribute10 = #{shiftCode}
AND EM.organization_id = #{orgName}
AND EM.EMPLOYEE_NUMBER = TAR.EMPLOYEE_NO AND TAR.Employee_No = TASO.Employee_No(+) AND TAR.TIME_AND_ATTENDANCE_DATE = TASO.TIME_AND_ATTENDANCE_DATE(+) AND 'Y' = TASO.CONFIRM_FLAG(+) AND TAR.Time_And_Attendance_Date BETWEEN to_date(#{dateFrom},'DD/MM/RRRR') AND to_date(#{dateTo},'DD/MM/RRRR') GROUP BY EM.Assignment_Category ,SUBSTR(EM.Email, 1, INSTR(EM.Email,'@')-1) ,EM.Full_Name_Local ,EM.EMPLOYEE_NUMBER ,EM.Grade_Title ,EM.Attribute10
